insert into public.admin_help_items(help_key,title_fa,body_fa,warning_fa,title_en,body_en,warning_en,active) values
('commerce.analytics','آمار فروشگاه','این صفحه نشان می‌دهد بازدید محصول‌ها چگونه به سبد، Checkout، سفارش و پرداخت تبدیل می‌شود. فروش، تعداد کالا، بازپرداخت و عملکرد هر محصول هم دیده می‌شود.',null,'Store analytics','See how product views turn into carts, checkout, orders and paid orders, plus revenue, units, refunds and product performance.',null,true),
('commerce.analytics.funnel','قیف خرید','قیف خرید کمک می‌کند بفهمی مشتری‌ها بیشتر در کدام مرحله ریزش می‌کنند؛ مثلاً محصول را می‌بینند اما به سبد اضافه نمی‌کنند یا Checkout را شروع می‌کنند ولی پرداخت نمی‌کنند.',null,'Purchase funnel','The funnel shows where customers drop off between product view, cart, checkout, order and payment.',null,true),
('commerce.analytics.product','آمار اختصاصی محصول','برای هر محصول بازدید، سبد خرید، شروع Checkout، تعداد سفارش، تعداد فروخته‌شده، فروش، موجودی و رضایت مشتری جداگانه نمایش داده می‌شود.',null,'Product analytics','Each product has its own views, carts, checkout starts, orders, units sold, revenue, inventory and customer rating analytics.',null,true)
insert into public.guidance_articles(article_key,area,route_prefix,title_fa,summary_fa,body_fa,title_en,summary_en,body_en,keywords,importance,related_help_keys,active,sort_order) values
('commerce.analytics.reading','commerce','/admin/commerce/analytics','چطور آمار فروشگاه را بخوانیم؟','از فروش کل تا تشخیص محصول پربازدید اما کم‌فروش','اول فروش و تعداد سفارش را ببین، بعد قیف خرید را بررسی کن. اگر بازدید زیاد ولی Add to Cart کم است، صفحه محصول یا قیمت نیاز به بررسی دارد. اگر Cart زیاد ولی پرداخت کم است، Checkout، ارسال یا اعتماد مشتری را بررسی کن. برای هر محصول صفحه آمار اختصاصی وجود دارد. در نسخه‌های پیشرفته‌تر سود، اثر تخفیف، منبع فروش، گردش موجودی و AI Insight هم از همین زیرساخت تحلیل می‌شوند.','How to read store analytics','From total revenue to products with traffic but weak sales','Start with revenue and paid orders, then inspect the purchase funnel. High views with low add-to-cart can indicate product-page or pricing issues. High carts with low payments can indicate checkout, shipping or trust friction. Every product has its own analytics page. Profit, discount efficiency, attribution, inventory turnover and AI insights build on the same data foundation.',array['آمار فروشگاه','فروش','محصول','قیف','conversion','commerce analytics','product analytics'],'important',array['commerce.analytics','commerce.analytics.funnel','commerce.analytics.product'],true,22)
